content.query:
let usr1 = SentinelOne
| where isnotempty(SrcUserName)
| project usr=SrcUserName;
let usr2 = SentinelOne
| where isnotempty(DataUserName)
| project usr=DataUserName;
let all_usr =
union isfuzzy=true usr1, usr2
| summarize cnt = dcount(usr)
| extend title = 'Users';
let agnt = SentinelOne
| where isnotempty(AgentId)
| summarize cnt = dcount(AgentId)
| extend title = 'Agents';
let alerts = SentinelOne
| where ActivityType == 3608
| summarize cnt = count()
| extend title = 'Alerts';
union isfuzzy=true all_usr, agnt, alerts

